-- Restore Theramore's Fall - Horde (map 999, scenario 72).
-- Spawn and text data were ported read-only from Legends of Azeroth Pandaria
-- 5.4.8 (build 18414), while scripts were adapted to the Legion 7.3.5 core.
-- Legion build 26972 DB2 data confirms scenario steps 179-183 and LFG 567.
START TRANSACTION;

-- Replace the incomplete map population and remove GUID-owned dependencies.
DELETE `ca` FROM `creature_addon` `ca`
INNER JOIN `creature` `c` ON `c`.`guid` = `ca`.`guid`
WHERE `c`.`map` = 999;
DELETE `wp` FROM `waypoint_data` `wp`
INNER JOIN `creature` `c` ON `c`.`guid` = `wp`.`id`
WHERE `c`.`map` = 999;
DELETE `cf` FROM `creature_formations` `cf`
INNER JOIN `creature` `c` ON `c`.`guid` = `cf`.`memberGUID`
WHERE `c`.`map` = 999;
DELETE `cf` FROM `creature_formations` `cf`
INNER JOIN `creature` `c` ON `c`.`guid` = `cf`.`leaderGUID`
WHERE `c`.`map` = 999;
DELETE `gec` FROM `game_event_creature` `gec`
INNER JOIN `creature` `c` ON `c`.`guid` = `gec`.`guid`
WHERE `c`.`map` = 999;
DELETE `pc` FROM `pool_creature` `pc`
INNER JOIN `creature` `c` ON `c`.`guid` = `pc`.`guid`
WHERE `c`.`map` = 999;
DELETE `geg` FROM `game_event_gameobject` `geg`
INNER JOIN `gameobject` `g` ON `g`.`guid` = `geg`.`guid`
WHERE `g`.`map` = 999;
DELETE `pg` FROM `pool_gameobject` `pg`
INNER JOIN `gameobject` `g` ON `g`.`guid` = `pg`.`guid`
WHERE `g`.`map` = 999;
DELETE FROM `creature` WHERE `map` = 999;
DELETE FROM `gameobject` WHERE `map` = 999;

